package app;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    public record OrderItem(String sku, int quantity) {
        public OrderItem {
            Objects.requireNonNull(sku, "sku");
            if (quantity <= 0) {
                throw new IllegalArgumentException("quantity must be positive");
            }
        }
    }

    public record PlaceOrderRequest(String customer, List<OrderItem> items) {
        public PlaceOrderRequest {
            Objects.requireNonNull(customer, "customer");
            Objects.requireNonNull(items, "items");
            items = List.copyOf(items);
        }
    }

    public record PlacedOrder(String orderId, Instant placedAt) {}

    @Transactional
    public PlacedOrder placeOrder(PlaceOrderRequest request) {
        Objects.requireNonNull(request, "request");
        if (request.items().isEmpty()) {
            throw new IllegalArgumentException("order must contain at least one item");
        }
        String orderId = UUID.randomUUID().toString();
        return new PlacedOrder(orderId, Instant.now());
    }
}

